import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_BASE_URL || '/api';
const API_TIMEOUT = Number(process.env.REACT_APP_API_TIMEOUT || 10000);

const api = axios.create({
  baseURL: API_BASE,
  timeout: API_TIMEOUT,
});

function compactParams(params = {}) {
  return Object.entries(params).reduce((acc, [key, value]) => {
    if (value === undefined || value === null || value === '') return acc;
    acc[key] = value;
    return acc;
  }, {});
}

export const getExecutionLiveSnapshot = async (params = {}) => {
  const response = await api.get('/executions/live', { params: compactParams(params) });
  return response.data;
};

export function buildExecutionLiveFeedWsUrl(params = {}) {
  const query = new URLSearchParams(compactParams(params)).toString();
  const path = `${API_BASE.replace(/\/$/, '')}/executions/live/ws${query ? `?${query}` : ''}`;

  if (/^https?:\/\//i.test(path)) {
    return path.replace(/^http/i, 'ws');
  }

  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  return `${protocol}//${window.location.host}${path.startsWith('/') ? path : `/${path}`}`;
}
